function pad({ bodies, selection, settings }) {
  const face = bodies.find(b => b.id === selection[0].body).faces.find(f => f.id === selection[0].face);
  const { u, v } = face.plane;
  const n = [u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0]];
  const center = face.signature.slice(3, 6);
  const h = settings.width / 2;
  const vertices = [[-h,-h,-0.01],[h,-h,-0.01],[h,h,-0.01],[-h,h,-0.01],[-h,-h,settings.height],[h,-h,settings.height],[h,h,settings.height],[-h,h,settings.height]]
    .map(([x,y,z]) => center.map((c,i) => c + x*u[i] + y*v[i] + z*n[i]));
  const triangles = [[0,2,1],[0,3,2],[4,5,6],[4,6,7],[0,1,5],[0,5,4],[1,2,6],[1,6,5],[2,3,7],[2,7,6],[3,0,4],[3,4,7]];
  return { vertices, triangles };
}
export default {
  partition(context) {
    const invalid = context.selection.some(ref => !context.bodies.find(b => b.id === ref.body).faces.find(f => f.id === ref.face).plane);
    return invalid ? { reason: "Raised pads require planar faces" } : { groups: context.selection.map(face => ({ faces: [face] })) };
  },
  validate(context) {
    if (context.selection.length !== 1) return [{ severity: "error", message: "A pad needs one planar face", faces: context.selection }];
    const ref = context.selection[0];
    const body = context.bodies.find(b => b.id === ref.body);
    const face = body.faces.find(f => f.id === ref.face);
    if (!face.plane) return [{ severity: "error", message: "Raised pads require planar faces", faces: [ref] }];
    if (context.settings.width ** 2 > face.signature[2]) {
      const neighbor = body.faces.find(f => f.id !== face.id && f.edges.some(e => face.edges.includes(e)));
      return [{ severity: "warning", message: "Pad width may extend beyond this face", faces: neighbor ? [ref, { body: body.id, face: neighbor.id }] : [ref], edges: face.edges.map(edge => ({ body: body.id, edge })) }];
    }
    return [];
  },
  preview(context) { return pad(context); },
  generate(context) { return [{ operation: "add", mesh: pad(context) }]; }
};
